insert into games (id, title, subtitle, description, themes, difficulty, min_players, max_players, duration_minutes, avg_rating, review_count, publisher, release_year) values
  ('00000000-0000-0000-0000-000000000001', '악마의 만찬', '귀족의 저녁 식사에서 벌어진 비극', '1887년 런던, 에드워드 경의 성대한 만찬에 초대받은 여섯 명의 귀족. 디저트가 나오기 전, 한 명이 쓰러졌다. 독살인가, 사고인가? 당신이 진실을 밝혀내야 한다.', array['victorian','horror'], 'intermediate', 4, 8, 150, 4.2, 128, '미스터리박스', 2022),
  ('00000000-0000-0000-0000-000000000002', '베니스의 밤', '가면 무도회 뒤에 숨겨진 음모', '화려한 베니스 가면 무도회. 모두가 가면을 쓴 이 밤, 누군가가 다이아몬드 목걸이와 함께 사라졌다. 10명의 참가자 중 범인은 단 한 명.', array['historical','modern'], 'advanced', 6, 10, 180, 4.8, 256, '플레이미스터리', 2021),
  ('00000000-0000-0000-0000-000000000003', '붉은 저택', '저주받은 가문의 비밀', '할로윈 밤, 오래된 저택에 모인 4명. 집주인이 사라지고, 문은 잠겼다. 새벽이 오기 전에 탈출하려면 저택의 비밀을 풀어야 한다.', array['horror'], 'beginner', 2, 4, 90, 3.5, 64, '다크게임즈', 2023),
  ('00000000-0000-0000-0000-000000000004', '서울 1987', '민주화의 봄, 그리고 한 형사의 죽음', '1987년 서울. 비 내리는 밤, 한 형사가 자신의 사무실에서 죽은 채 발견되었다. 자살? 아니면 타살? 그가 쫓던 사건의 진실이 밝혀지면 많은 것이 바뀐다.', array['historical','modern'], 'advanced', 4, 6, 200, 4.9, 512, '코리아미스터리', 2020),
  ('00000000-0000-0000-0000-000000000005', '마법사의 탑', '판타지 왕국의 황위 쟁탈전', '마법사들의 결투 대회 날 밤, 왕국의 수석 마법사가 독살되었다. 왕위 계승권을 둘러싼 음모가 뒤엉킨 마법사의 탑에서 진실을 찾아라.', array['fantasy'], 'beginner', 4, 8, 120, 4.1, 89, '판타지게임즈', 2023),
  ('00000000-0000-0000-0000-000000000006', '갤럭시 특급', '우주 정거장에서 벌어진 살인', '2157년, 태양계를 순회하는 호화 우주선 갤럭시 특급. 화성-지구 구간에서 억만장자 승객이 객실에서 숨진 채 발견됐다. 혐의자는 모두 우주선 안에 있다.', array['scifi'], 'intermediate', 4, 8, 150, 4.4, 156, '스페이스미스터리', 2022);
